{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Whole-person membership care</title>
  <meta name="description" content="A membership practice blending evidence-informed modalities for lasting wellness. Education-first, personalized plans.">
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="layout-split">
  <header class="site-header">
    <div class="brand">
      <svg class="logo" viewBox="0 0 100 100" aria-hidden="true">
        <defs>
          <linearGradient id="g1" x1="0" x2="1">
            <stop offset="0" stop-color="#6ea05b" />
            <stop offset="1" stop-color="#4a8b8f" />
          </linearGradient>
        </defs>
        <circle cx="50" cy="50" r="40" fill="url(#g1)" />
        <path d="M35 60 C45 30, 65 30, 75 60" stroke="#fff" stroke-width="4" fill="none" stroke-linecap="round" />
      </svg>
      <div class="brand-text">
        <strong class="business">{{BUSINESS_NAME}}</strong>
        <small class="tag">{{TAGLINE}}</small>
      </div>
    </div>
    <nav class="nav">
      <button id="nav-toggle" aria-expanded="false">Menu</button>
      <ul id="nav-list">
        <li><a href="/">Home</a></li>
        <li><a href="/services.html">Offerings</a></li>
        <li><a href="/conditions.html">Concerns</a></li>
        <li><a href="/approach.html">How We Work</a></li>
        <li><a href="/about.html">Meet</a></li>
        <li><a href="/book.html" class="accent">Join as a Member</a></li>
      </ul>
    </nav>
  </header>

  <main>
    <!-- HERO: split diagonal -->
    <section id="hero" class="hero split">
      <div class="hero-left">
        <h1>Membership care that sees the whole you</h1>
        <p class="lead">Join a thoughtful integrative practice where education, personalized plans, and steady follow-up replace quick fixes. Memberships prioritize ongoing partnership, prevention, and practical tools for daily life.</p>
        <div class="hero-actions">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <a class="btn ghost" href="/about.html">Meet {{PRACTITIONER_NAME}}</a>
        </div>
        <ul class="meta">
          <li>Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a></li>
          <li>Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
          <li>Serving: {{CITY}}, {{STATE}}</li>
        </ul>
      </div>
      <div class="hero-right">
        <div class="pattern-wrap" role="img" aria-label="Abstract organic pattern background">
          <!-- SVG pattern referenced as background image in CSS -->
        </div>
      </div>
    </section>

    <!-- MYTH VS TRUTH -->
    <section id="myth_vs_truth" class="card-grid">
      <h2>A few myths, re-told as practical truths</h2>
      <div class="cards">
        <article class="card">
          <h3>Myth: Quick fixes fix everything</h3>
          <p>Truth: Healing is often incremental. We teach small, sustainable changes that compound over months rather than promise instant cures.</p>
        </article>
        <article class="card">
          <h3>Myth: Natural means unscientific</h3>
          <p>Truth: We favor evidence-informed herbs, nutrition, and lifestyle interventions and explain what the science does — and doesn't — support.</p>
        </article>
        <article class="card">
          <h3>Myth: One treatment fits all</h3>
          <p>Truth: Your plan is built around your history, labs (optional), and life context. Memberships allow iterative refinement.</p>
        </article>
      </div>
    </section>

    <!-- PILLARS -->
    <section id="pillars" class="split-diagonal">
      <h2>Our four steady pillars</h2>
      <div class="pillars-grid">
        <div>
          <h4>Education-first</h4>
          <p>We prioritize understanding: why symptoms happen and what practical steps help most people like you.</p>
        </div>
        <div>
          <h4>Individualized plans</h4>
          <p>Nutrition, movement, mind-body tools, and targeted supplements when appropriate — chosen for your unique profile.</p>
        </div>
        <div>
          <h4>Ongoing support</h4>
          <p>Regular check-ins, adjustments, and direct messaging to keep momentum without surprises.</p>
        </div>
        <div>
          <h4>Measurement & learning</h4>
          <p>Optional labs and tracking help us see what works. Testing is educational, not coercive.</p>
        </div>
      </div>
    </section>

    <!-- CASE NOTES -->
    <section id="case_notes" class="case-notes">
      <h2>Short case notes — how membership changes the story</h2>
      <div class="notes">
        <article>
          <p><strong>Client:</strong> Busy parent with chronic sleep troubles. <strong>Approach:</strong> Small evening ritual + tailored nutrition + 6-week check. <strong>Outcome:</strong> Gradual 45–60 minute improvement in sleep onset and daytime energy. (Individual results vary.)</p>
        </article>
        <article>
          <p><strong>Client:</strong> Office worker with digestion complaints. <strong>Approach:</strong> Food log, gentle botanicals, and mindful eating exercises. <strong>Outcome:</strong> Reduced bloating and clearer eating cues over 10 weeks. (Not a guarantee.)</p>
        </article>
      </div>
      <p class="disclaimer">These notes are illustrative. Holistic care focuses on education and supportive strategies; outcomes depend on many factors.</p>
    </section>

    <!-- FAQ -->
    <section id="faq" class="faq">
      <h2>Common questions</h2>
      <details>
        <summary>What is included in a membership?</summary>
        <p>Memberships include an initial intake, personalized care plan, scheduled follow-ups, secure messaging, and access to educational resources. Optional labs or specialist referrals are available when helpful.</p>
      </details>
      <details>
        <summary>Do you promise cures for chronic conditions?</summary>
        <p>No. We do not promise cures. We aim to reduce symptoms, improve function, and increase resilience through whole-person strategies and education.</p>
      </details>
      <details>
        <summary>Are labs required?</summary>
        <p>Labs are optional and used as an educational tool. We recommend testing only when results would change the plan.</p>
      </details>
    </section>

    <!-- CTA -->
    <section id="cta" class="cta">
      <div class="cta-inner">
        <h2>Ready for a different approach?</h2>
        <p>Memberships are for people who want steady guidance instead of one-off fixes. Let's build habits that fit your life.</p>
        <a class="btn primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
        <p class="small">Prefer a quick question? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div>
      <p>&copy; <span id="year"></span> {{BUSINESS_NAME}} • {{CITY}}, {{STATE}}</p>
      <p>Practitioner: {{PRACTITIONER_NAME}}, {{CREDENTIALS}}</p>
    </div>
    <nav class="foot-nav">
      <a href="/privacy.html">Privacy</a>
      <a href="/contact.html">Contact</a>
      <a href="/pricing.html">Plans</a>
    </nav>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
