{"path":"assets/css/styles.css","content":"/* Core layout and visual system — split diagonal with organic SVG pattern */
:root{
  --bg:#fbfdf9; --muted:#6b7370; --accent1:#6ea05b; --accent2:#4a8b8f; --card:#ffffff; --glass:rgba(255,255,255,0.7);
  --max-width:1100px; --radius:14px;
}
*{box-sizing:border-box}
html,body{height:100%;margin:0;font-family:system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; color:#133;}
.site-header{display:flex;align-items:center;justify-content:space-between;padding:18px;max-width:1200px;margin:0 auto;width:92%;}
.brand{display:flex;gap:12px;align-items:center}
.logo{width:56px;height:56px}
.brand-text{line-height:1}
.brand-text .business{display:block;font-size:1rem}
.brand-text .tag{font-size:0.8rem;color:var(--muted)}
.nav{position:relative}
#nav-toggle{display:none;background:none;border:1px solid var(--muted);padding:8px 12px;border-radius:8px}
.nav ul{display:flex;gap:12px;list-style:none;margin:0;padding:0}
.nav a{color:inherit;text-decoration:none;padding:8px 10px;border-radius:8px}
.nav a.accent{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#fff}

/* Split diagonal hero */
.layout-split .hero.split{display:grid;grid-template-columns:1fr 1fr;gap:0;align-items:stretch;min-height:64vh;max-width:1200px;margin:20px auto;border-radius:var(--radius);overflow:hidden;position:relative}
.hero-left{padding:48px;background:linear-gradient(180deg, rgba(255,255,255,0.9), rgba(250,252,250,0.95));}
.hero-left h1{margin:0 0 12px;font-size:2.2rem;color:var(--accent2)}
.hero-left .lead{color:var(--muted);max-width:48ch}
.hero-actions{margin-top:18px;display:flex;gap:12px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;text-decoration:none;border:1px solid transparent}
.btn.primary{background:linear-gradient(90deg,var(--accent1),var(--accent2));color:#fff}
.btn.ghost{background:transparent;color:var(--accent2);border-color:var(--accent2)}
.meta{list-style:none;padding:16px 0 0 0;margin:0;color:var(--muted);font-size:0.9rem}
.meta li{margin-top:6px}

.hero-right{background:linear-gradient(135deg, #f6fbf8 40%, rgba(74,139,143,0.06) 100%);position:relative;display:flex;align-items:center;justify-content:center;padding:30px}
.pattern-wrap{width:100%;height:100%;background-image:url('../img/pattern.svg');background-repeat:no-repeat;background-size:cover;background-position:center}

/* Card grid */
.card-grid{max-width:1100px;margin:36px auto;padding:28px;width:92%}
.card-grid h2{margin-top:0}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:14px}
.card{background:var(--card);border-radius:12px;padding:18px;box-shadow:0 6px 18px rgba(18,23,20,0.06)}
.card h3{margin-top:0;color:var(--accent2)}

/* pillars split diagonal accent */
.split-diagonal{background:linear-gradient(180deg, rgba(110,160,91,0.06), rgba(74,139,143,0.02));padding:30px;border-radius:12px;margin:32px auto;max-width:1100px;width:92%}
.pillars-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}
.pillars-grid h4{margin:0 0 6px}

/* case notes */
.case-notes{max-width:1100px;margin:28px auto;padding:20px;width:92%}
.notes{display:grid;gap:12px}
.case-notes .disclaimer{font-size:0.85rem;color:var(--muted)}

/* FAQ */
.faq{max-width:900px;margin:28px auto;padding:20px}
.faq details{background:var(--card);padding:12px;border-radius:10px;margin:10px 0}

/* CTA */
.cta{background:linear-gradient(90deg, rgba(110,160,91,0.06), rgba(74,139,143,0.03));padding:36px;border-radius:12px;margin:32px auto;text-align:center;max-width:1000px;width:92%}
.cta .large{padding:14px 22px;font-size:1.05rem}
.cta .small{color:var(--muted);margin-top:12px}

/* Footer */
.site-footer{max-width:1200px;margin:34px auto;padding:18px 24px;display:flex;justify-content:space-between;align-items:center;color:var(--muted)}
.foot-nav a{margin-left:12px;color:var(--muted);text-decoration:none}

/* Responsive */
@media (max-width:900px){
  .hero.split{grid-template-columns:1fr;min-height:70vh}
  .cards{grid-template-columns:1fr}
  .pillars-grid{grid-template-columns:1fr 1fr}
  #nav-toggle{display:inline-block}
  .nav ul{position:absolute;right:0;top:54px;background:var(--card);padding:10px;border-radius:10px;box-shadow:0 10px 30px rgba(0,0,0,0.06);display:none;flex-direction:column}
  .nav ul.show{display:flex}
}

/* subtle diagonal overlay */
.layout-split .hero.split::after{content:"";position:absolute;left:0;top:0;bottom:0;right:50%;background:linear-gradient(120deg, rgba(255,255,255,0.0) 0%, rgba(255,255,255,0.6) 60%);pointer-events:none}
"} 
{"path":"assets/js/main.js","content":"// Minimal interactivity: nav toggle, smooth scroll, year injection
document.addEventListener('DOMContentLoaded',function(){
  var navToggle=document.getElementById('nav-toggle');
  var navList=document.getElementById('nav-list');
  if(navToggle){
    navToggle.addEventListener('click',function(){
      var expanded = this.getAttribute('aria-expanded') === 'true';
      this.setAttribute('aria-expanded', String(!expanded));
      navList.classList.toggle('show');
    });
  }

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click',function(e){
      e.preventDefault();
      var id = this.getAttribute('href').slice(1);
      var el = document.getElementById(id);
      if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
    });
  });

  // year
  var y = new Date().getFullYear();
  var el = document.getElementById('year');
  if(el) el.textContent = y;

  // Minor accessibility: allow details toggle via keydown
  document.querySelectorAll('.faq details').forEach(function(d){
    d.addEventListener('keydown',function(e){ if(e.key === 'Enter' || e.key === ' ') d.open = !d.open });
  });
});"} 
